//! First-class image, Voyage and System One protocol adapters; persistence remains external.
use gateway_core::{GatewayError,provider::UpstreamProvider};
use serde::{Serialize,Deserialize};
use serde_json::{json,Value};
use crate::types::*;
fn prepared(provider:UpstreamProvider,url:&str,surface:ClientSurface,raw:&Value,body:Value,options:&PrepareOptions,decode:ResponseDecode)->PreparedRequest{let model=body["model"].as_str().unwrap_or("").to_owned();PreparedRequest{provider,url:url.into(),method:"POST".into(),headers:Headers::from([("Authorization".into(),format!("Bearer {}",options.auth.secret)),("Content-Type".into(),"application/json".into()),("Accept".into(),"application/json".into())]),body,decode:DecodePlan{provider,surface,decode,model:raw["model"].as_str().unwrap_or(&model).into(),upstream_model:model,response_id:options.response_id.clone(),created_at:options.created_at,stream:false,request:raw.clone(),tool_names:ToolMap::new(),reasoning_summary:None},warnings:vec![]}}
pub fn prepare_systemone(raw:&Value,options:&PrepareOptions)->Result<PreparedRequest,GatewayError>{let object=raw.as_object().ok_or_else(||invalid("Invalid JSON body",""))?;if let Some(key)=object.keys().find(|k|!["state","questions","model"].contains(&k.as_str())){return Err(GatewayError::new(400,format!("Unsupported key: {key}"),Some("invalid_request_error")))}if !raw["state"].is_object(){return Err(GatewayError::new(400,"state must be an object",Some("invalid_request_error")))}let questions=raw["questions"].as_object().ok_or_else(||GatewayError::new(400,"questions must be an object",Some("invalid_request_error")))?;if questions.is_empty()||questions.len()>24{return Err(GatewayError::new(400,"questions must hold between 1 and 24 questions",Some("invalid_request_error")))}if questions.iter().any(|(name,q)|name.trim().is_empty()||name.encode_utf16().count()>120||!q.is_object()||!matches!(q["type"].as_str(),Some("noul"|"choice"|"score"))){return Err(GatewayError::new(400,"questions must be typed noul, choice, or score objects",Some("invalid_request_error")))}let model=raw.get("model").map_or(Some("~typesafe/jev-latest"),Value::as_str).ok_or_else(||invalid("model must be a string","model"))?;let base=model.strip_prefix('~').unwrap_or(model);let suffix=base.strip_prefix("typesafe/").unwrap_or("");if model.len()>80||suffix.is_empty()||suffix.len()>64||!suffix.chars().all(|c|c.is_ascii_lowercase()||c.is_ascii_digit()||matches!(c,'.'|'_'|'-'))||!suffix.chars().next().is_some_and(|c|c.is_ascii_lowercase()||c.is_ascii_digit()){return Err(invalid("model must be a TypeSafe System One model","model"))}let upstream=if model.starts_with('~'){model.to_owned()}else{format!("~{model}")};Ok(prepared(UpstreamProvider::Openrouter,"https://openrouter.ai/api/v1/systemone",ClientSurface::SystemOne,raw,json!({"model":upstream,"state":raw["state"],"questions":raw["questions"]}),options,ResponseDecode::SystemOne))}
pub fn decode_systemone(value:&Value)->Result<Value,GatewayError>{if !value["answers"].is_object(){return Err(GatewayError::new(502,"System One upstream invalid response",Some("openrouter_upstream_invalid_response")).with_type("server_error"))}Ok(value.clone())}
pub fn systemone_usage(value:&Value)->Option<Value>{let input=value["input_tokens"].as_f64()?;let output=value["output_tokens"].as_f64()?;let mut usage=json!({"input_tokens":input,"output_tokens":output,"total_tokens":input+output,"input_tokens_details":{"cached_tokens":0}});if value["cost"].is_number(){usage["cost"]=value["cost"].clone();}Some(usage)}
#[derive(Clone,Debug,Serialize,Deserialize)]
pub struct EmbeddingsProfile{pub model:String,pub inputs:Vec<String>,pub input_type:String,pub dimensions:u64,pub encoding_format:String,pub truncation:bool,pub cache_profile_key:String,pub total_chars:usize}
pub fn parse_embeddings(raw:&Value,job:bool)->Result<EmbeddingsProfile,GatewayError>{let object=raw.as_object().ok_or_else(||invalid("Invalid JSON body",""))?;for key in object.keys(){if !["dimensions","encoding_format","input","input_type","model","truncation"].contains(&key.as_str())&&(key!="user"||job){return Err(invalid(format!("Unrecognized request argument supplied: {key}"),key))}}
    let model=raw.get("model").map_or(Some("voyage-4-large"),Value::as_str).ok_or_else(||invalid("model must be a string","model"))?;if model!="voyage-4-large"{return Err(invalid("Unsupported embeddings model","model"))}let dimensions=raw.get("dimensions").map_or(Some(1024),Value::as_u64).filter(|d|[256,512,1024,2048].contains(d)).ok_or_else(||invalid("dimensions must be one of: 256, 512, 1024, 2048","dimensions"))?;let encoding=raw.get("encoding_format").map_or(Some("float"),Value::as_str).filter(|v|["float","base64"].contains(v)&&(!job||*v=="float")).ok_or_else(||invalid("encoding_format must be float or base64","encoding_format"))?;
    let input_type=raw.get("input_type").map(Value::as_str).unwrap_or(if job{None}else{Some("document")}).filter(|v|*v=="query"||*v=="document").ok_or_else(||invalid("input_type must be one of: \"query\", \"document\"","input_type"))?;let truncation=raw.get("truncation").map_or(Some(true),Value::as_bool).ok_or_else(||invalid("truncation must be a boolean","truncation"))?;if raw.get("user").is_some_and(|v|!v.is_null()&&!v.is_string()){return Err(invalid("user must be a string","user"))}let inputs=if let Some(input)=raw["input"].as_str(){vec![input.to_owned()]}else{raw["input"].as_array().ok_or_else(||invalid("input must be a string or an array of strings","input"))?.iter().map(|v|v.as_str().map(str::to_owned).ok_or_else(||invalid("input must be a string or an array of strings","input"))).collect::<Result<Vec<_>,_>>()?};if inputs.is_empty()||inputs.len()>128{return Err(invalid("input must contain between 1 and 128 strings","input"))}let mut total=0;for input in &inputs{let len=input.encode_utf16().count();if len>20_000{return Err(invalid(format!("Input too large: {len} chars (max 20000)"),"input"))}total+=len;if total>100_000{return Err(invalid(format!("Request too large: {total} chars total (max 100000)"),"input"))}}
    let cache_profile_key=json!(["voyage-profile-v2",model,input_type,dimensions,"float",encoding,truncation]).to_string();Ok(EmbeddingsProfile{model:model.into(),inputs,input_type:input_type.into(),dimensions,encoding_format:encoding.into(),truncation,cache_profile_key,total_chars:total})
}
pub fn prepare_embeddings(raw:&Value,options:&PrepareOptions)->Result<PreparedRequest,GatewayError>{let profile=parse_embeddings(raw,false)?;let input=if profile.inputs.len()==1{json!(profile.inputs[0])}else{json!(profile.inputs)};let body=json!({"model":profile.model,"input":input,"input_type":profile.input_type,"output_dimension":profile.dimensions,"output_dtype":"float","truncation":profile.truncation});Ok(prepared(UpstreamProvider::Voyage,"https://api.voyageai.com/v1/embeddings",ClientSurface::Embeddings,raw,body,options,ResponseDecode::Voyage))}
pub fn decode_embeddings(value:&Value,plan:&DecodePlan)->Result<Value,GatewayError>{let profile=parse_embeddings(&plan.request,false)?;let rows=value["data"].as_array().ok_or_else(||malformed("Voyage embeddings returned invalid JSON."))?;if rows.len()!=profile.inputs.len(){return Err(malformed("Voyage embeddings returned a different vector count."))}let mut data=vec![];for(index,row)in rows.iter().enumerate(){let vector=row["embedding"].as_array().filter(|v|v.len()==profile.dimensions as usize&&v.iter().all(Value::is_number)).ok_or_else(||malformed("Voyage embedding dimensions or values are invalid."))?;let embedding=if profile.encoding_format=="base64"{let mut bytes=vec![];for value in vector{bytes.extend_from_slice(&(value.as_f64().unwrap_or(0.0)as f32).to_le_bytes());}json!(base64_encode(&bytes))}else{json!(vector)};data.push(json!({"object":"embedding","index":index,"embedding":embedding}));}let total=value["usage"]["total_tokens"].as_f64().filter(|v|v.is_finite()).map(|v|v.max(0.0).trunc());Ok(json!({"object":"list","model":profile.model,"data":data,"usage":{"prompt_tokens":total,"total_tokens":total}}))}
pub fn base64_encode(bytes:&[u8])->String{const CHARS:&[u8;64]=b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";let mut result=String::new();for chunk in bytes.chunks(3){let a=chunk[0]as usize;let b=chunk.get(1).copied().unwrap_or(0)as usize;let c=chunk.get(2).copied().unwrap_or(0)as usize;result.push(CHARS[a>>2]as char);result.push(CHARS[((a&3)<<4)|(b>>4)]as char);result.push(if chunk.len()>1{CHARS[((b&15)<<2)|(c>>6)]as char}else{'='});result.push(if chunk.len()>2{CHARS[c&63]as char}else{'='});}result}
#[derive(Clone,Debug,Serialize,Deserialize)]
pub struct ImagePlan{pub responses:Value,pub count:u64,pub request_ids:Vec<String>,pub codex_only:bool}
pub fn prepare_image(raw:&Value,base_model:&str,edit:bool,request_id:&str)->Result<ImagePlan,GatewayError>{let mut body=raw.clone();let object=body.as_object_mut().ok_or_else(||invalid("Invalid JSON body",""))?;for key in ["model","n","size","quality","background","output_format","output_compression","input_fidelity","moderation","response_format","stream","partial_images","style"]{if object.get(key).is_some_and(Value::is_null){object.remove(key);}}for key in object.keys(){let shared=["model","prompt","n","size","quality","background","output_format","output_compression","stream","partial_images","user"];let valid=shared.contains(&key.as_str())||if edit{["images","mask","input_fidelity","moderation"].contains(&key.as_str())}else{["moderation","response_format","style"].contains(&key.as_str())};if !valid{return Err(invalid(format!("Unrecognized request argument supplied: {key}"),key))}}
    if body.get("style").is_some(){return Err(invalid("style is not supported because this gateway uses the Responses image-generation tool.","style"))}let prompt=body["prompt"].as_str().filter(|s|!s.trim().is_empty()).ok_or_else(||invalid("Image requests must include a prompt.","prompt"))?;if prompt.chars().count()>32_000{return Err(invalid("prompt must contain no more than 32000 characters.","prompt"))}if body.get("model").is_some_and(|v|v.as_str().is_none_or(|s|s.trim().is_empty())){return Err(invalid("model must be a non-empty string.","model"))}if body.get("user").is_some_and(|v|!v.is_string()){return Err(invalid("user must be a string.","user"))}let count=body.get("n").map_or(Some(1),Value::as_u64).filter(|n|*n>=1&&*n<=10).ok_or_else(||invalid("n must be an integer from 1 to 10.","n"))?;
    for(key,allowed)in [("quality",["low","medium","high","auto"].as_slice()),("background",["transparent","opaque","auto"].as_slice()),("output_format",["png","jpeg","webp"].as_slice()),("moderation",["low","auto"].as_slice()),("input_fidelity",["low","high"].as_slice())]{if body.get(key).is_some_and(|v|v.as_str().is_none_or(|v|!allowed.contains(&v))){return Err(invalid(format!("{key} must be {}.",allowed.join(", ")),key))}}
    if body.get("output_compression").is_some_and(|v|!v.as_u64().is_some_and(|n|n<=100)){return Err(invalid("output_compression must be an integer from 0 to 100.","output_compression"))}if body.get("size").is_some_and(|v|v.as_str().is_none_or(|s|s.trim().is_empty())){return Err(invalid("size must be a non-empty string.","size"))}if body.get("stream").is_some_and(|v|!v.is_boolean()){return Err(invalid("stream must be a boolean.","stream"))}if body["stream"]==true||body.get("partial_images").is_some(){return Err(invalid("Streaming image responses are not supported by this gateway.",if body["stream"]==true{"stream"}else{"partial_images"}))}if body.get("response_format").is_some_and(|v|v!="b64_json"){return Err(invalid("response_format must be b64_json.","response_format"))}
    let mut tool=json!({"type":"image_generation","action":if edit{"edit"}else{"generate"}});if let Some(model)=body["model"].as_str(){tool["model"]=json!(model.trim());}else if edit{tool["model"]=json!("gpt-image-1.5");}for key in ["size","quality","background","output_format","output_compression","moderation"]{if let Some(value)=body.get(key){tool[key]=value.clone();}}
    let input=if edit{let images=body["images"].as_array().filter(|i|!i.is_empty()&&i.len()<=16).ok_or_else(||invalid("images must contain between 1 and 16 image references","images"))?;let mut content=vec![json!({"type":"input_text","text":prompt})];for image in images{let image=normalize_image_reference(image,false)?;content.push(json!({"type":"input_image","image_url":image["image_url"]}));}if let Some(mask)=body.get("mask"){tool["input_image_mask"]=normalize_image_reference(mask,true)?;}if let Some(fidelity)=body.get("input_fidelity"){tool["input_fidelity"]=fidelity.clone();}json!([{"role":"user","content":content}])}else{json!(prompt)};
    let mut responses=json!({"model":base_model,"input":input,"tools":[tool],"tool_choice":{"type":"image_generation"}});if let Some(user)=body.get("user"){responses["user"]=user.clone();}let kind=if edit{"edits"}else{"generations"};let request_ids=(0..count).map(|i|if i==0{request_id.into()}else{format!("{request_id}:image:{kind}:{}",i+1)}).collect();Ok(ImagePlan{responses,count,request_ids,codex_only:true})
}
pub fn normalize_image_reference(value:&Value,mask:bool)->Result<Value,GatewayError>{let object=value.as_object().filter(|o|o.keys().all(|k|k=="image_url")).ok_or_else(||invalid("Invalid image reference","images"))?;let url=object["image_url"].as_str().map(str::trim).filter(|s|!s.is_empty()&&s.len()<=20_971_520).ok_or_else(||invalid("Invalid image URL","images"))?;if let Some(data)=url.strip_prefix("data:"){let(media,payload)=data.split_once(";base64,").ok_or_else(||invalid("Invalid image data URL","images"))?;let media=match media.to_lowercase().as_str(){"image/png"|"image/x-png"=>"image/png","image/jpeg"|"image/jpg"=>"image/jpeg","image/webp"=>"image/webp",_=>return Err(invalid("Unsupported image type","images"))};if payload.is_empty()||payload.len()%4!=0||!payload.chars().all(|c|c.is_ascii_alphanumeric()||matches!(c,'+'|'/'|'=')){return Err(invalid("Invalid image base64","images"))}if mask&&media!="image/png"{return Err(invalid("mask must be a PNG image","mask"))}Ok(json!({"image_url":format!("data:{media};base64,{payload}")}))}else if !mask&&(url.starts_with("https://")||url.starts_with("http://")){Ok(json!({"image_url":url}))}else{Err(invalid("Invalid image reference",if mask{"mask"}else{"images"}))}}
pub fn extract_images(payload:&Value)->Vec<Value>{payload["output"].as_array().into_iter().flatten().filter(|v|v["type"]=="image_generation_call").filter_map(|v|v["result"].as_str().filter(|s|!s.is_empty()).map(|result|{let mut image=json!({"b64_json":result});if let Some(prompt)=v["revised_prompt"].as_str(){image["revised_prompt"]=json!(prompt);}image})).collect()}
#[derive(Clone,Debug)]
pub struct MultipartFile{pub name:String,pub filename:String,pub content_type:String,pub bytes:Vec<u8>}
pub fn multipart_image_references(files:&[MultipartFile])->Result<(Vec<Value>,Option<Value>),GatewayError>{let mut images=vec![];let mut mask=None;let mut total=0;for file in files{total+=file.bytes.len();if file.bytes.is_empty()||file.bytes.len()>=50*1024*1024||total>50*1024*1024{return Err(invalid("Image files exceed the 50 MiB input limit","image"))}let media=match file.content_type.split(';').next().unwrap_or("").trim().to_lowercase().as_str(){"image/png"|"image/x-png"=>"image/png","image/jpeg"|"image/jpg"=>"image/jpeg","image/webp"=>"image/webp",_=>return Err(invalid("Unsupported image media type","image"))};let reference=json!({"image_url":format!("data:{media};base64,{}",base64_encode(&file.bytes))});match file.name.as_str(){"image"|"image[]"=>images.push(reference),"mask" if mask.is_none()&&media=="image/png"=>mask=Some(reference),_=>return Err(invalid("Invalid multipart image field","image"))}}if images.is_empty()||images.len()>16{return Err(invalid("image must contain between 1 and 16 files","image"))}Ok((images,mask))}
